commands.acceptanceScript:
#!/bin/sh
set +e
failures=0
run() {
  name=$1
  shift
  "$@" > "/tmp/plan143/$name.json" 2> "/tmp/plan143/$name.stderr"
  result=$?
  printf '%s=%s\n' "$name" "$result" >> /tmp/plan143/accept-status
  if [ "$result" -ne 0 ]; then failures=$((failures+1)); fi
}
run performance-after bunx playwright test performance.e2e.ts --workers=1 --reporter=json
for host in vanilla vue foldkit; do
  case "$host" in
    vanilla) config=playwright.config.ts ;;
    vue) config=apps/vue/playwright.config.ts ;;
    foldkit) config=apps/foldkit/playwright.config.ts ;;
  esac
  run "playwright-$host" bunx playwright test -c "$config" upstream-playwright.e2e.ts --workers=1 --reporter=json
  run "cypress-$host" bunx playwright test -c "$config" upstream-cypress.e2e.ts --repeat-each=3 --workers=1 --reporter=json
  run "component-$host" bunx playwright test -c "$config" upstream-component.e2e.ts --repeat-each=3 --workers=1 --reporter=json
  files="base-edge.e2e.ts edge-stacking.e2e.ts edge-recipes.e2e.ts renderer-contract.e2e.ts renderer-props.e2e.ts edge-geometry-recipes.e2e.ts subflows-recipes.e2e.ts"
  case "$host" in
    vanilla) files="$files graph-renderers.e2e.ts schema-studio.e2e.ts next-slices.e2e.ts" ;;
    vue) files="$files minimap.e2e.ts final-wiring.e2e.ts" ;;
    foldkit) files="$files edge-interaction.e2e.ts schema-studio.e2e.ts minimap.e2e.ts minimap-options.e2e.ts" ;;
  esac
  run "affected-$host" bunx playwright test -c "$config" $files --workers=1 --reporter=json
 done
exit "$failures"
